        [
            'id' => 'pivottable', 'ikon' => 'table-2', 'tajuk' => 'PivotTable', 'jenis' => 'kad',
            'sub' => 'A PivotTable summarizes thousands of rows into a summary table without formulas. Start with a question, then arrange the fields.',
            'item' => [
                ['Create', 'Click one cell in an Excel table → Insert → <strong>PivotTable</strong> → choose New Worksheet → OK. The field list opens on the right.'],
                ['Four areas', '<strong>Rows</strong> = categories down the side. <strong>Columns</strong> = categories across the top. <strong>Values</strong> = numbers being summarized. <strong>Filters</strong> = a filter for the whole PivotTable.'],
                ['From question to layout', '"Total sales for each region by month": Region to Rows, Date to Columns, Amount to Values.'],
                ['Group dates', 'A date field in Rows or Columns is usually grouped automatically. To change it, right-click a date → <strong>Group</strong> → choose Months and Years. Months alone merges January of every year.'],
                ['Group numbers', 'Right-click a value in Rows → Group → fill in Starting at, Ending at and By. For example, ages 20 to 59 by 10.'],
                ['Layout for copying', 'Design → Report Layout → <strong>Show in Tabular Form</strong>, then <strong>Repeat All Item Labels</strong>. Every row carries its full labels.'],
                ['Update', 'PivotTable Analyze → <strong>Refresh</strong> after the source data changes. If the source is a plain range that grows, use Change Data Source or turn the source into an Excel table.'],
                ['Refer to a PivotTable value', 'Click a PivotTable cell while writing a formula. Excel writes <code>GETPIVOTDATA</code>, which keeps pointing at the right value even when the PivotTable layout changes.'],
            ],
            'nota' => 'The "Cannot group that selection" error usually means the date column contains text or blank cells. Clean the source data, then Refresh.',
        ],
        [
            'id' => 'pivot-values', 'ikon' => 'sigma', 'tajuk' => 'Summarizing values in a PivotTable', 'jenis' => 'jadual',
            'sub' => 'Right-click a value → Value Field Settings. Summarize Values By picks the calculation. Show Values As picks how the value is displayed.',
            'kepala' => ['Option', 'Question it answers', 'Example'],
            'baris' => [
                ['Summarize Values By → <strong>Sum</strong>', 'What is the total?', 'Total sales for each region'],
                ['Summarize Values By → <strong>Count</strong>', 'How many records?', 'Number of transactions per branch. Text fields are counted with Count by default.'],
                ['Summarize Values By → <strong>Average</strong>, <strong>Max</strong>, <strong>Min</strong>', 'What is the average, highest or lowest?', 'Average value of one order'],
                ['Show Values As → <strong>% of Grand Total</strong>', 'What share of the whole?', 'Each product\'s contribution to total sales'],
                ['Show Values As → <strong>% of Column Total</strong> / <strong>% of Row Total</strong>', 'What share within each column or row?', 'Product mix within each month'],
                ['Show Values As → <strong>Difference From</strong>', 'How much did it change compared with another item?', 'Base field Date, Base item (previous) = change from the previous month'],
                ['Show Values As → <strong>% Difference From</strong>', 'By what percentage did it change?', 'Month-over-month growth'],
                ['Show Values As → <strong>Running Total In</strong>', 'What is the cumulative total so far?', 'Cumulative sales since January'],
                ['Show Values As → <strong>Rank Largest to Smallest</strong>', 'Who is at the top?', 'Ranking of sales representatives'],
            ],
            'nota' => 'Drag the same field into Values twice to show the actual value and its percentage side by side. Set the format with the <strong>Number Format</strong> button in Value Field Settings, not Ctrl+1 on the cells, so the format survives a Refresh.',
        ],
        [
            'id' => 'chart-choice', 'ikon' => 'chart-column', 'tajuk' => 'Choose a chart by question', 'jenis' => 'jadual',
            'sub' => 'A good chart answers one question. Decide the question first, then pick the chart type.',
            'kepala' => ['Question', 'Chart', 'Note'],
            'baris' => [
                ['Which category is largest?', 'Clustered Column or Clustered Bar', 'Use Bar when category labels are long. Sort from largest to smallest.'],
                ['How does a value change over time?', 'Line', 'The horizontal axis is time at equal intervals. More than four lines is hard to read.'],
                ['What share of the whole?', 'Pie or Doughnut, 100% Stacked Column', 'Use Pie only for two to five parts. Beyond that, use a sorted Bar chart.'],
                ['How are values distributed?', 'Histogram', 'Example: distribution of exam marks in bands of 10 marks.'],
                ['Are two numbers related?', 'Scatter', 'Example: advertising spend against sales. Add a Trendline if needed.'],
                ['Two measures on different scales', 'Combo with Secondary Axis', 'Example: sales (RM) as columns and margin (%) as a line.'],
                ['Actual against target', 'Clustered Column with the target series as a Line', 'The reader sees the gap for every month at a glance.'],
            ],
            'nota' => 'Avoid 3D charts, shadows and gradients. They distort the sizes the reader sees and make comparison harder. The vertical axis of column and bar charts starts at zero.',
        ],
        [
            'id' => 'chart-tools', 'ikon' => 'trending-up', 'tajuk' => 'Build and tidy charts', 'jenis' => 'kad',
            'sub' => 'Steps for creating a chart, combining two chart types and tying a chart to a PivotTable.',
            'item' => [
                ['Quick chart', 'Select the data, press Alt+F1 for a chart on the same sheet or F11 for a new chart sheet. Insert → <strong>Recommended Charts</strong> suggests charts based on the data.'],
                ['Combo chart', 'Click the chart → Chart Design → <strong>Change Chart Type</strong> → Combo. Pick a type for each series and check <strong>Secondary Axis</strong> for the series on a different scale.'],
                ['PivotChart', 'Click the PivotTable → PivotTable Analyze → <strong>PivotChart</strong>. The chart follows every filter, slicer and Refresh on that PivotTable.'],
                ['Hide field buttons', 'On a PivotChart: PivotChart Analyze → <strong>Field Buttons</strong> → Hide All. The chart looks clean in a dashboard.'],
                ['Chart elements', 'The <strong>+</strong> button next to the chart: axis titles, data labels, legend, gridlines. Remove anything that does not help the reader.'],
                ['Sparklines', 'Insert → <strong>Sparklines</strong> → Line. A small chart in one cell that shows the trend of each row.'],
                ['Chart template', 'Right-click the chart → <strong>Save as Template</strong> (.crtx file). Reuse the same colors and formatting in every report.'],
            ],
            'nota' => 'A good chart title states the answer, not just the topic. For example, "Q3 sales up 12% on Q2", not "Sales by quarter".',
        ],
        [
            'id' => 'slicers-timeline', 'ikon' => 'filter', 'tajuk' => 'Slicers and timelines', 'jenis' => 'kad',
            'sub' => 'Clickable filter buttons. Dashboard users filter the data without opening a filter list.',
            'item' => [
                ['Insert a slicer', 'Click in an Excel table or PivotTable → Insert → <strong>Slicer</strong> → check the fields → OK. One slicer is created for each field.'],
                ['Pick several items', 'Hold Ctrl and click the items. The <strong>Clear Filter</strong> button in the slicer corner removes the filter.'],
                ['One slicer, many PivotTables', 'Select the slicer → Slicer tab → <strong>Report Connections</strong> → check the other PivotTables. Only PivotTables that share the same data source can be connected.'],
                ['Timeline', 'Click in a PivotTable → PivotTable Analyze → <strong>Insert Timeline</strong> → check a date field. Timelines work with PivotTables only, not plain tables.'],
                ['Time level', 'Click the arrow on the timeline to switch between Years, Quarters, Months and Days. Drag along the bar to select a period.'],
                ['Slicer settings', 'Right-click the slicer → <strong>Slicer Settings</strong> → <em>Hide items with no data</em> removes buttons that give no result.'],
                ['Layout', 'Slicer tab → Columns to arrange the buttons across. Use Align on the same tab to line up several slicers.'],
            ],
            'nota' => 'PivotTables built from the same table share a data source. If Report Connections does not list another PivotTable, that PivotTable was built from a different source.',
        ],
        [
            'id' => 'power-query', 'ikon' => 'database', 'tajuk' => 'Power Query basics', 'jenis' => 'jadual',
            'sub' => 'Power Query records every cleaning step. Next month, the new data is cleaned with one Refresh.',
            'kepala' => ['Step', 'How', 'Note'],
            'baris' => [
                ['Load data', 'Data → Get Data → From File → <strong>From Text/CSV</strong>, <strong>From Workbook</strong> or <strong>From Folder</strong>. For a table in this workbook: Data → <strong>From Table/Range</strong>.', 'Choose <strong>Transform Data</strong>, not Load, to open the Power Query Editor.'],
                ['Read the steps', 'The <strong>Applied Steps</strong> pane on the right of the editor', 'Every action becomes one step. Click a step to see the data at that point. Delete a step with the X icon next to it.'],
                ['Headers and data types', 'Home → <strong>Use First Row as Headers</strong>. Click the icon left of a column name to change its data type.', 'Set Date and Decimal Number types correctly. A wrong type breaks totals and date grouping.'],
                ['Clean', 'Transform → <strong>Format</strong> → Trim. Home → <strong>Remove Rows</strong>. Home → <strong>Replace Values</strong>. Transform → <strong>Fill</strong> → Down.', 'The same as cleaning on the sheet, but repeated by itself on every Refresh.'],
                ['Unpivot', 'Select the columns to keep as they are (for example Product) → Transform → <strong>Unpivot Other Columns</strong>', 'Columns Jan, Feb, Mar … become two columns: Attribute (month) and Value (amount). This long format is what a PivotTable needs.'],
                ['Bring in columns from another table', 'Home → <strong>Merge Queries</strong> → pick the second table and the matching column → Join Kind', 'Like XLOOKUP for a whole table. After the merge, click the expand icon on the new column to choose which columns to bring in.'],
                ['Stack rows from another table', 'Home → <strong>Append Queries</strong>', 'For January, February and March data with the same columns. From Folder does this for every file in one folder.'],
                ['Summarize', 'Transform → <strong>Group By</strong>', 'Totals or counts by category before the data is loaded into Excel.'],
                ['Load into Excel', 'Home → <strong>Close &amp; Load To</strong> → Table, PivotTable Report or Only Create Connection', 'Ctrl+Alt+F5 (Refresh All) repeats every step on the latest data.'],
            ],
            'nota' => 'Power Query does not change the source file. It reads the source and builds a new result. If a column name in the source file changes, the steps that refer to that name fail. Look for the error in the Applied Steps pane.',
        ],
        [
            'id' => 'dashboard', 'ikon' => 'layout-template', 'tajuk' => 'One-sheet dashboard', 'jenis' => 'kad',
            'sub' => 'One sheet that answers the reader\'s main questions in a few seconds. Data and calculations live on other sheets.',
            'item' => [
                ['Workbook structure', 'Three layers: a <strong>Data</strong> sheet (tables or Power Query output), an <strong>Analysis</strong> sheet (PivotTables and formulas), a <strong>Dashboard</strong> sheet (KPIs, charts, slicers).'],
                ['KPIs top left', 'The reader\'s eye starts at the top left. Put three to five headline numbers there: total sales, growth, number of customers.'],
                ['KPI cards', 'Large cells that refer to a PivotTable with <code>GETPIVOTDATA</code> or to a table with <code>SUMIFS</code>. Add a small label and a comparison with the previous period.'],
                ['Charts in the middle', 'Two to four charts, each answering one question. Same size, aligned to the cell grid.'],
                ['Slicers at the side', 'Slicers and timelines in one column on the left or one row at the top. Connect every slicer to all PivotTables through Report Connections.'],
                ['One accent color', 'Gray for all ordinary data. One color for what the reader must see, for example the current month or a value below target.'],
                ['Finishing', 'View → uncheck <strong>Gridlines</strong>. Use the same number formats across the sheet. Hide the Analysis sheet if readers do not need it.'],
                ['Sharing', 'For PDF: Page Layout → Orientation → Landscape, then Scale to Fit → Width 1 page and Height 1 page. For on-screen use, test on an ordinary laptop screen, not only a large monitor.'],
            ],
            'nota' => 'Before you build, write down three questions the dashboard must answer. Any chart or KPI that does not answer one of them can go.',
        ],
        [
            'id' => 'excel-to-power-bi', 'ikon' => 'arrow-up-right', 'tajuk' => 'From Excel to Power BI', 'jenis' => 'jadual',
            'sub' => 'Power BI Desktop uses the same ideas as this chapter. The table below maps what you already know.',
            'kepala' => ['In Excel', 'In Power BI', 'Difference'],
            'baris' => [
                ['Excel table', 'Table in the data model', 'Power BI holds several tables and the relationships between them, not one sheet.'],
                ['Power Query', 'Power Query (Transform data)', 'The same editor and steps. What you learned in Excel carries over directly.'],
                ['PivotTable', 'Matrix visual', 'The same Rows, Columns and Values, but on a report canvas.'],
                ['Formulas and calculated columns', 'Measures and calculated columns in DAX', 'A measure is calculated for the current filters, like a value in a PivotTable. It is not a cell formula.'],
                ['Slicers and timelines', 'Slicer visual', 'One slicer filters every visual on the page by default.'],
                ['Charts', 'Chart visuals', 'The same chart types. Clicking one bar filters the other visuals on the page.'],
                ['Sending the .xlsx file', 'Publish the report to the Power BI service', 'Readers open the report in a browser. Data can refresh on a schedule.'],
            ],
            'nota' => 'Stay in Excel when the data fits on one worksheet (the limit is 1,048,576 rows), only a few people read the report, and anyone must be able to edit the calculations. Consider Power BI when the data passes that limit, several sources must be combined and refreshed on a schedule, or many people need to read the same interactive report. Power BI Desktop runs on Windows only.',
        ],
    ],
];
